using DungeonCrawler.Dungeon.Generation;
using System.Text;
using DungeonCrawler.Dungeon;
using DungeonCrawler.Enemies;

namespace DungeonCrawler.Adventure.Ai;

/// <summary>Prompt text. Defaults are embedded; the game may override them from data/adventures/prompts/*.txt.</summary>
public sealed class PromptTemplates
{
    public string Rules { get; init; } = DefaultRules;
    public string OutlineTask { get; init; } = DefaultOutlineTask;
    public string FloorTask { get; init; } = DefaultFloorTask;
    public string BarksTask { get; init; } = DefaultBarksTask;
    /// <summary>An author-written campaign bible (markdown). When set, every planning call carries it as a cached system block and the outline is told to follow it.</summary>
    public string Brief { get; init; } = "";

    public static PromptTemplates Default { get; } = new();

    public const string BriefPreamble = """
        Campaign bible, written by the game's author. It is the campaign: take the title, premise, antagonist, cast (names, roles, secrets, bodies, personality labels, floors), mystery and clues, choices and flags, factions, tier beats, the twenty-floor table (titles, themes, layouts, objectives, what happens), puzzles, boss names and lines, taunts and narration from it, and invent only what it leaves open. Where the bible and the rules conflict (a layout or objective the game forbids, a line too long), the rules win and the bible's intent is kept as closely as the rules allow. Lines quoted in the bible are to be used as written.
        """;

    public const string DefaultRules = """
        You are the dungeon master for a first-person, real-time, party dungeon crawler. Four adventurers (a Warrior, a Rogue, a Ranger and a Mage) descend twenty procedurally generated floors in four tiers of five: Crypt, Caves, Forge, Abyss. Every fifth floor ends in a boss arena; the boss locks the stairs down until it dies. There is no town and no return to the surface: the whole story happens on the way down.

        You write plans, not prose. Each reply is a single JSON document matching the schema you are given. The game validates every plan and repairs what it can, so respect the rules below; anything impossible is silently removed and the floor gets duller.

        Floors: the geometry is generated by the game and described to you as a menu: rooms (index, size, height level, flags, neighbours, hops from the start room, free cells), an ASCII map (< up stairs, > down stairs, . floor, : upper-level floor, # wall, + door, / ramp, O pit, S secret wall, $ chest, k key, L lever, ^ trap, e generator spawn), and the enemy roster with a cost per enemy. Room indices are the only way to refer to rooms.

        Room roles: Start (the room with the up stairs, forced), Exit (down stairs, forced), Arena (boss floors, forced), Treasury (vault rooms), Camp (rooms flagged bandit-camp), Ruin (rooms flagged ruin), Gate, Shrine, Cell, Barracks, Kennel, Lair, Hall, Passage. Give every room a short evocative name (at most 40 characters) that fits its role and the tier.

        Some big rooms hold a structure. A room flagged gate has a wall across it with one arched opening flanked by braziers: a Defend collective with Objective Kind Gate and Ref = that room's index holds the opening. A room flagged bandit-camp has a dilapidated hut with a campfire where bandits squat: the roster's bandit entries may only be used in camp rooms (a Guard collective there, three to five of them, never elsewhere) and a camp must never be left empty. Rooms flagged pond or stream have water on the floor; it is walkable but slows whoever wades through it. A room flagged ruin is a collapsed colonnade: broken and fallen columns, rubble mounds and a heaved floor, with cover to fight around. Rubble mounds elsewhere (flag rubble) are heaps bodies must path around.

        Hordes: a room flagged nest has breaches in its walls. Give every nest room a Horde (up to eight per floor, one per nest room): {Id, Name, Room, Members [{EnemyId, Count}], Trigger Enter (the party steps into the room), Chest (a chest in that room is opened) or Alarm (any Alarm collective's runner arrives), Line spoken as it breaks loose}. Members are mostly roster entries marked horde (the cheaper one is fodder that dies in a hit or two, the dearer one a brute); from floor 4 a few of the tier's own creatures may march with them, at most a quarter of the total and never more than eight. Size hordes to the depth: three to five on floor 1, growing every floor to fifty or sixty by floor 20, with brutes and big creatures taking a larger share the deeper you go. Hordes stream out over several seconds and count against nothing in the budget. Vary the triggers so hordes break out of different parts of the floor at different moments.

        Collectives are enemy groups with a goal. Guard: hold a post in their room, chase intruders within a leash and walk back. Defend: protect an objective (a chest by spawn index, a vault Door or Lever by vault index, the Stairs, or an Npc by id); they intercept anyone approaching it and fall back onto it. Patrol: walk a Route of connected room indices (the first is their room); the game walks the loop. Alarm: on contact their fastest member sprints to the AlarmTarget collective to wake it; give them a RallyRoom near their target. Any collective may have a RallyRoom to regroup in when half of it dies. Rules: 1 to 5 collectives, 1 to 6 members each, never in the Start room, only Guard or Defend inside a vault, total enemies between the minimum and maximum given, total cost within the budget (the budget already reflects how strong the party is), a room can only hold as many enemies as it has free cells. Loners are single enemies with no group. Ledge archers and cellar ambushers are placed by the game; do not count them.

        Chests and Traps you add are extra on top of the generator's (at most 2 chests and 3 traps; trap kinds Spikes, Fire, Gas); never in the Start room.

        NPCs: at most two per floor, never in a vault or the arena. Each has a dialogue script: a flat list of nodes with ids, a Start node id, and per node a spoken Line and 1 to 4 choices. A choice may have a Next node id and an Effect: None, AcceptQuest, DeclineQuest, TurnIn, Farewell, Choose (sets Flag, a short snake_case word the run remembers), Betray (the NPC turns on the party; only on an NPC with a Betrayal). Conversations must be short: two to four nodes. An NPC with a QuestId must have a node with an AcceptQuest choice and one with a TurnIn choice (Decide and Betrayal quests need neither); the game only shows Accept/Decline while the quest is offered and TurnIn once it is complete. An NPC may be a campaign Cast member (CastId): then they wear that name and voice, and what they say must fit their Role and hint at, but never state, their Secret before its floor. NPCs, quests, choices and narration may carry RequiresFlag or ForbidsFlag: the game keeps them out until the flag's state matches, so write both branches of a consequence on the floor where it lands.

        Quests, one per NPC at most, templates: KillTarget (Params.TargetCollective = a collective id on this floor), Recover (Params.ItemRoom = a room at least two hops from the start, Params.ItemName), Escort (Params.EscortNpc = the giver's own id; the NPC must not be in the Exit room; they follow the party to the stairs down), HoldOut (Params.WaveCollective = a collective id, Params.Waves 1 to 3; enemies of that kind attack in waves at the NPC), Investigate (Params.ClueRooms = 2 to 4 distinct rooms, not the start; Params.ClueName; one clue lies in each room and the party brings them back; this is how a Mystery clue from the outline reaches the floor: put the clue's text in the giver's TurnIn dialogue), Decide (the giver's script offers two or more Choose choices with different Flags; whichever the party picks completes the quest at once and is remembered), Betrayal (the giver has a Betrayal {EnemyId, Count 1 to 4} and a choice with Effect Betray; when the party takes it the NPC vanishes and those creatures stand in their place, the first wearing the NPC's name; killing them completes the quest). Lines: Offer, Accept, Decline, Complete, Fail (each at most 220 characters). Reward.Xp between 50 and 500 times the floor number divided by 10, Reward.Table "table.chest" or null.

        Boss (boss floors only): Name, optional SignatureOverride (Slam, Volley, Charge, Summon), IntroLine and DeathLine spoken by the boss. Narration: an IntroLine for the floor and optional lines with Trigger Enter, RoomEnter (with Room), BossSeen, BossDead, QuestDone, QuestFailed. Keep every line at most 220 characters.

        Voice and tone: the campaign is bleak and the people in it are sardonic; the situations are sometimes absurd and the characters know it. Dry humour, gallows wit, physical detail; no modern idiom, no fourth wall, no jokes that break the dread. Every spoken line costs money to voice, so the whole campaign has a budget of about eighty spoken lines: quiet floors get an IntroLine and nothing else (no NPC, no extra narration); story floors get an IntroLine, one NPC with a script of two to four nodes, and a quest. Make each line earn its place.

        Objective floors: the game deals some floors a trial of the antagonist's (the menu's OBJECTIVE line says which: jailbreak, toxic, ritual, shiftingvault). Its rooms (JAIL, SHRINE) and its people belong to the game; plan the rest of the floor around it and keep NPCs, hordes and patrol routes out of those rooms.

        Voices: every character sounds like someone. Give each NPC and cast member a Persona: VoiceStyle (a few words on the voice and manner, at most 120 characters; make them distinct people, not everyone frightened), DefaultDelivery (one of whisper, weary, calm, warm, cheerful, sly, pleading, angry, mocking, shout, booming, frantic) and Voice (one of the voice names listed). Any Line may set Delivery to one of those ids when it should not be said in the character's usual manner (a shout, a whisper).

        Taunts: the antagonist runs the dungeon and throws its trials at the party; they yell at, mock and curse the party as things happen. The campaign's Taunts are two or three lines per Trigger (FloorEnter, Capture, Freed, AllFreed, GasThickens, GasLethal, WrongLever, GateShift, VaultOpened, RitualStart, RitualistDown, WaveBreak, RitualDone, ObjectiveDone, Idle, MemberDowned, PartyWiped, Descend, Reinforcements), FloorEnter ones naming their Objective. Spiteful, theatrical, in the antagonist's own voice; free to curse, period oaths and modern profanity both. Every taunt has a CleanLine: the same line with the cursing taken out. Tokens {party} (the lead's name), {floor} and {prisoner} are filled in.

        Continuity: the campaign outline is the arc: its Cast are the people who come back, its Mystery is the question the clues answer, its floor Story beats say who appears where. Reference its antagonist, factions and tier beats; carry threads forward from the memory notes (rescued NPCs may reappear, failed quests leave marks, flags set by choices change who is waiting and what they say, the antagonist reacts to how the party fights). Adapt difficulty to the notes: a struggling party gets fewer, weaker groups and a kinder quest; a dominant party gets tighter defences and alarms. Never break the rules to do it.
        """;

    public const string DefaultOutlineTask = """
        Design the campaign for this run and the plan for floor 1.

        Campaign: a Title (at most 60 characters), a Synopsis (two or three sentences), an Antagonist (Name, Epithet) who waits on floor 20, a Cast of four to six recurring characters (Id such as cast_warden, Name, Role, Secret: what they hide and on which floor it comes out; make them original people with wants of their own, not stock hermits and widows: a rival crew's captain who keeps losing to the party, a jailer who wants to be arrested, a cartographer mapping the wrong dungeon), a Mystery (Question, Truth, three to five Clues each on a different story floor, PayoffFloor 12-19, Payoff), one Faction per tier (Id, Name, EnemyIds from that tier's pool), four Tiers (Index 0-3, Theme, Beat: what this tier's floors are about, BossName for the tier's boss, optional BossSignature, EnterLine spoken by the narrator on the tier's first floor), and exactly twenty Floors (Floor 1-20, Title, Mood, Layout: one of the layout ids listed below, chosen so the descent keeps changing shape (every id at least once, never the same on two floors in a row, floor 1 standard; null lets the game deal one), Story: empty for a quiet floor, else the beat: which cast id appears, which clue, choice or betrayal happens, which earlier flag it answers; make about eight of the twenty story floors, including the payoff floor, spread through the descent with at least one per tier; SpecOverrides: leave every field null unless a floor should be unusual; EnemyCount 3-16, ChestCount 1-4, LockedChestCount 0-2, TrapCount 0-8, VaultCount 0-2, LedgeCount 0-2, PitCount 0-2, SecretCount 0-3, HighRoomChance 0-1, StructureCount 0-3 for gatehouses, bandit camps and ruins, WaterCount 0-3 for ponds and streams, RubbleCount 0-6, NestCount 0-2 for horde breaches). Plan at least one Decide floor whose flag a later floor answers with a RequiresFlag or ForbidsFlag branch, and one Betrayal by a cast member the party has met before. Barks: leave empty here. Taunts: two or three per trigger as the rules say, each with a CleanLine. Antagonist.Persona and every Cast member's Persona: VoiceStyle, DefaultDelivery, Voice from the lists. ArcNotes: private notes to your future self about threads to pay off, at most 600 characters.

        Floor1: the full plan for floor 1 using the menu below. Floor 1 should teach: one or two small groups, a Guard and maybe a Patrol, no Alarm. Floor 1 is a story floor if the outline says so: then one cast member with a short script and a simple quest.
        """;

    public const string DefaultFloorTask = """
        Write the plan for this floor. Use the campaign outline (its floor title, mood and Story beat for this floor, the tier beat, the factions, the Cast and the Mystery) and the memory notes, including the flags the party's choices have set. Choose collectives and goals that make the layout matter: defend the chest room, patrol the loop, post an alarm group near the stairs that wakes the defenders. A quiet floor (empty Story) has an IntroLine and no NPC. A story floor has one NPC (the cast member the beat names, with CastId) with a script of two to four nodes, one quest that carries the beat (an Investigate for a clue, a Decide for a choice, a Betrayal when the beat says so), and nothing spoken beyond that.
        """;

    public const string DefaultBarksTask = """
        Write a bark bank for the four party members: for each member exactly 24 lines, three per Trigger (Kill, Hurt, Loot, LevelUp, BossSeen, Possess, Downed, Revived), each at most 90 characters, in the member's own voice given their class and the campaign's tone. Members[].Member is the member's name exactly as given.
        """;
}

public sealed record PartyMemberInfo(string Name, string ClassName);

/// <summary>Builds the three kinds of planning requests. The system blocks are byte-stable across floors so they cache.</summary>
public static class PromptBuilder
{
    public const int OutlineMaxTokens = 48000; // thinking counts against it; the outline is 10k tokens of JSON on its own
    public const int FloorMaxTokens = 16000;
    public const int BarksMaxTokens = 8000;

    /// <summary>The system blocks every call shares: the rules, then the author's bible when there is one. Byte-stable so they cache.</summary>
    private static PromptBlock[] SystemBlocks(PromptTemplates t, params PromptBlock[] extra)
    {
        var blocks = new List<PromptBlock> { new(t.Rules.Trim(), Cache: true) };
        if (!string.IsNullOrWhiteSpace(t.Brief)) blocks.Add(new PromptBlock(PromptTemplates.BriefPreamble.Trim() + "\n\n" + t.Brief.Trim(), Cache: true));
        blocks.AddRange(extra);
        return blocks.ToArray();
    }

    public static ClaudeRequest Outline(PromptTemplates t, string model, ulong seed, IReadOnlyList<TierProfile> tiers, IReadOnlyDictionary<string, EnemyProfile> roster, IReadOnlyList<PartyMemberInfo> party, FloorMenu floor1, IReadOnlyList<ThemeProfile>? themes = null)
    {
        var user = new StringBuilder();
        user.AppendLine(t.OutlineTask.Trim());
        if (!string.IsNullOrWhiteSpace(t.Brief)) user.AppendLine("Follow the campaign bible in the system prompt: this outline is that bible in the schema's shape.");
        user.AppendLine();
        user.AppendLine($"Run seed: {seed}.");
        user.AppendLine("Party: " + string.Join(", ", party.Select(p => $"{p.Name} the {p.ClassName}")) + ".");
        user.AppendLine();
        user.AppendLine("Tiers and their enemy pools:");
        foreach (var tier in tiers)
        {
            var pool = string.Join(", ", tier.EnemyPool.Select(id => roster.TryGetValue(id, out var p) ? $"{id} ({p.Name}, {p.Kind})" : id));
            var boss = roster.TryGetValue(tier.BossId, out var bp) ? $"{tier.BossId} ({bp.Name}, signature {bp.Signature})" : tier.BossId;
            user.AppendLine($"- Tier {tier.Index} {tier.DisplayName}: {pool}; boss {boss}");
            var looks = themes == null ? new List<ThemeProfile>() : ThemeProfile.ForTier(themes, tier.Index).ToList();
            if (looks.Count > 0) user.AppendLine($"  themes for this tier (Floors[].Theme): {string.Join("; ", looks.Select(l => $"{l.Id} = {l.DisplayName}{(l.Description != "" ? ", " + l.Description : "")}"))}");
        }
        user.AppendLine();
        user.AppendLine("Floor layouts (Floors[].Layout): " + string.Join("; ", LayoutKinds.All.Select(k => $"{LayoutKinds.Id(k)} = {LayoutKinds.Describe(k)}")) + ". Boss floors: " + string.Join(", ", LayoutKinds.BossKinds.Select(LayoutKinds.Id)) + " only.");
        user.AppendLine("Voices a Persona may name (Voice): " + string.Join("; ", Voice.Voices.Catalog.Where(c => c.Name != Voice.Voices.Narrator && c.Name != Voice.Voices.Boss && c.Name != Voice.Voices.Villain).Select(c => $"{c.Name} = {c.Sound}")) + ". Deliveries: " + string.Join(", ", Voice.Deliveries.Ids) + ".");
        user.AppendLine("Floor objectives (Floors[].Objective), the antagonist's trials thrown at the party: " + string.Join("; ", FloorObjectives.All.Select(k => $"{FloorObjectives.Id(k)} = {FloorObjectives.Describe(k)}")) + ". About eight of the twenty floors, never floor 1 or a boss floor, never two in a row, each kind at least once; null leaves the floor to the game.");
        user.AppendLine();
        user.AppendLine("Floor 1 menu:");
        user.AppendLine(RenderMenu(floor1));
        return new ClaudeRequest("outline", model, SystemBlocks(t), user.ToString(), PlanSchemas.For<OutlineWithFirstFloor>(), "xhigh", OutlineMaxTokens);
    }

    public static ClaudeRequest Floor(PromptTemplates t, string model, CampaignPlan campaign, FloorMenu menu, string memorySummary)
    {
        var user = new StringBuilder();
        user.AppendLine(t.FloorTask.Trim());
        user.AppendLine();
        if (campaign.OutlineFor(menu.Floor) is { } outline && (outline.Title != "" || outline.Mood != "" || outline.Theme != null))
            user.AppendLine($"This floor in the outline: \"{outline.Title}\" ({outline.Mood}){(outline.Theme != null ? $", look: {outline.Theme}" : "")}, shape: {menu.Layout}.");
        if (campaign.TierFor(menu.TierIndex) is { } tier) user.AppendLine($"Tier beat: {tier.Beat}");
        user.AppendLine();
        user.AppendLine("Memory notes:");
        user.AppendLine(string.IsNullOrWhiteSpace(memorySummary) ? "(none yet: this is the first floor the party reaches after the outline)" : memorySummary.Trim());
        user.AppendLine();
        user.AppendLine($"Floor {menu.Floor} menu:");
        user.AppendLine(RenderMenu(menu));
        if (!string.IsNullOrWhiteSpace(t.Brief)) user.AppendLine("The campaign bible in the system prompt describes this floor: its puzzle, its people and their lines. Use them.");
        var system = SystemBlocks(t, new PromptBlock("Campaign outline (JSON):\n" + PlanFormat.Serialize(OutlineForPrompt(campaign)), Cache: true));
        return new ClaudeRequest($"floor{menu.Floor}", model, system, user.ToString(), PlanSchemas.For<FloorPlan>(), menu.Floor <= 5 ? "medium" : "high", FloorMaxTokens);
    }

    public static ClaudeRequest Barks(PromptTemplates t, string model, CampaignPlan campaign, IReadOnlyList<PartyMemberInfo> party)
    {
        var user = new StringBuilder();
        user.AppendLine(t.BarksTask.Trim());
        user.AppendLine();
        user.AppendLine("Members: " + string.Join(", ", party.Select(p => $"{p.Name} ({p.ClassName})")) + ".");
        user.AppendLine($"Campaign: {campaign.Title}. {campaign.Synopsis}");
        return new ClaudeRequest("barks", model, SystemBlocks(t), user.ToString(), PlanSchemas.For<BarkBank>(), "medium", BarksMaxTokens);
    }

    /// <summary>The outline without the per-floor plans' bulk: everything the floor call needs for continuity.</summary>
    private static CampaignPlan OutlineForPrompt(CampaignPlan c) => new()
    {
        Title = c.Title, Synopsis = c.Synopsis, Antagonist = c.Antagonist, Factions = c.Factions, Tiers = c.Tiers, Floors = c.Floors, ArcNotes = c.ArcNotes, Source = c.Source, GameSeed = c.GameSeed,
    };

    public static string RenderMenu(FloorMenu m)
    {
        var sb = new StringBuilder();
        sb.AppendLine($"Floor {m.Floor}, tier {m.TierIndex} ({m.TierName}), {m.Layout} layout{(LayoutKinds.TryParse(m.Layout, out var shape) && shape != LayoutKind.Standard ? $" ({LayoutKinds.Describe(shape)})" : "")}{(m.BossFloor ? $", BOSS FLOOR: {m.BossName} ({m.BossId}) waits in the arena" : "")}{(m.Objective != "none" ? $", OBJECTIVE {m.Objective}: {m.ObjectiveNote}; the stairs stay sealed until it is met, and its rooms and people belong to the game, not the plan" : "")}.");
        sb.AppendLine($"Enemy budget: cost {m.Budget:0.0}, between {m.MinEnemies} and {m.MaxEnemies} enemies (the generator would have placed {m.TargetEnemies}). Vaults: {m.VaultCount}. Generator chests: {m.GeneratorChests} (spawn indices 0-{Math.Max(0, m.GeneratorChests - 1)}).");
        sb.AppendLine("Roster (id: name, kind, cost):");
        foreach (var e in m.Roster) sb.AppendLine($"- {e.Id}: {e.Name}, {e.Kind}, cost {e.Cost:0.00}{(e.IsBandit ? ", bandit (camp rooms only)" : "")}{(e.IsHorde ? ", horde (nest rooms only, Hordes[] entries)" : "")}");
        sb.AppendLine("Rooms (index: size WxH, level, flags, neighbours, hops from start, free cells, chests):");
        foreach (var r in m.Rooms)
        {
            var flags = new List<string>();
            if (r.IsStart) flags.Add("START");
            if (r.IsExit) flags.Add("EXIT");
            if (r.IsArena) flags.Add("ARENA");
            if (r.IsVault) flags.Add($"VAULT({r.VaultKind})");
            if (r.IsJail) flags.Add("JAIL (the objective's; no NPCs or patrols here)");
            if (r.IsShrine) flags.Add("SHRINE (the objective's; no NPCs or hordes here)");
            if (r.HasLedge) flags.Add("ledge");
            if (r.HasCellar) flags.Add("pit+cellar");
            if (r.HasSecret) flags.Add("secret");
            if (r.DeadEnd) flags.Add("dead-end");
            if (r.HasGate) flags.Add("gate");
            if (r.IsCamp) flags.Add("bandit-camp");
            if (r.IsRuin) flags.Add("ruin");
            if (r.HasNest) flags.Add($"nest({r.Mouths} mouths)");
            if (r.Water == "Pond") flags.Add("pond");
            if (r.Water == "Stream") flags.Add("stream");
            sb.AppendLine($"- {r.Index}: {r.W}x{r.H}, level {r.Level}, [{string.Join(" ", flags)}], neighbours {string.Join(",", r.Neighbours)}, hops {r.HopsFromStart}, free {r.FreeCells}, chests [{string.Join(",", r.Chests)}]");
        }
        sb.AppendLine("Map:");
        sb.Append(m.Ascii);
        return sb.ToString();
    }
}
